MATCH (:PlantItem {tag: 'LSLL-23023'})-[:is_located_in]->(u:PlantSection)
RETURN DISTINCT u.unit_id AS unit_id
ORDER BY unit_id;

MATCH (:PlantItem {tag: 'V-4801'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (e:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(head:ProcessInstrumentationFunction {loop_tag: 'LSHH-39006'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'F-201'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (v:PlantItem {tag: 'V-1701'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'EJ-2501'}), (b:PlantItem {tag: 'EJ-2503'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH p = shortestPath((a)-[:line_to*]->(b))
         WHERE ALL(n IN nodes(p) WHERE n.tag <> 'E-2503')
       } AS reachable

MATCH (d:PlantItem {tag: 'D-901'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'V-4701'})-[:line_to]-(v:Valve)<-[:control]-(actuator:PlantItem)<-[:send_signal_to*1..]-(loop:ProcessControlFunction)
RETURN DISTINCT loop.tag AS tag
ORDER BY tag;

MATCH (i:PlantItem {tag: 'LT-10027'})-[:is_located_in]->(u:PlantSection)
RETURN DISTINCT u.unit_id AS unit_id
ORDER BY unit_id;

MATCH (equipment:Equipment)-[:measured_by]->(instrument:PlantItem {loop_tag: 'TI-16050'})
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(f:ProcessInstrumentationFunction {loop_tag: 'LIC-22063'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(sensor:PlantItem)
WHERE EXISTS {
  MATCH (sensor)-[:send_signal_to*0..]->(f:ProcessInstrumentationFunction {loop_tag: 'LSHH-4013'})
}
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'EA-1301'}), (b:PlantItem {tag: 'V-1301'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (v:PlantItem:SpringLoadedGlobeSafetyValve {unit_id: '35'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (e:PlantItem {tag: 'P-603'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'E-902'}), (b:PlantItem {tag: 'P-904'}), (d:PlantItem {tag: 'D-901'})
WHERE EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE y <> d)+ (b)
}
RETURN a.tag AS from_tag, b.tag AS to_tag

MATCH (a:PlantItem {tag: 'E-902'}), (b:PlantItem {tag: 'P-904'}), (d:PlantItem {tag: 'D-901'})
WHERE EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE x <> d AND y <> d)+ (b)
}
RETURN a.tag AS from_tag, b.tag AS to_tag

MATCH (:PlantItem {tag: 'EA-1601'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (v:PlantItem:PressureVessel {unit_id: '25'})
RETURN v.tag AS tag
