MATCH (a:PlantItem {tag: 'F-4502'}), (b:PlantItem {tag: 'H-4601'})
RETURN a.tag AS source, b.tag AS target, EXISTS {
  MATCH (a)((x:PlantItem WHERE x.tag <> 'E-4601')-[:line_to]->(y:PlantItem WHERE y.tag <> 'E-4601'))+(b)
} AS reachable_without_E4601

MATCH (a:PlantItem {tag: 'TK-5002'}), (b:PlantItem {tag: 'P-5001'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (a:PlantItem {tag: 'P-4903'}), (b:PlantItem {tag: 'TK-5003'})
RETURN EXISTS {
  MATCH (a) ((n)-[:line_to]->(m) WHERE n.tag <> 'TK-5002')+ (b)
} AS can_flow_without_TK_5002

MATCH (a:PlantItem {tag: 'TK-1001'}), (b:PlantItem {tag: 'F-1101'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'TK-3904'}), (b:PlantItem {tag: 'E-4001'})
RETURN EXISTS {
  MATCH p = (a)-[:line_to*1..]->(b)
  WHERE NONE(n IN nodes(p) WHERE n.tag = 'FV-39010')
} AS reachable_without_FV-39010

MATCH (a:PlantItem {tag: 'TK-3904'}), (b:PlantItem {tag: 'E-4001'})
RETURN EXISTS {
  MATCH p = (a)-[:line_to*1..]->(b)
  WHERE NONE(n IN nodes(p) WHERE n.tag = 'FV-39010')
} AS reachable_without_FV_39010

MATCH (a:PlantItem {tag: 'P-602'}), (b:PlantItem {tag: 'P-905'}), (v:PlantItem:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-2901'}), (b:PlantItem {tag: 'V-3501'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
           WHERE x.tag <> 'D-3001' AND y.tag <> 'D-3001')+ (b)
       } AS can_flow

MATCH (a:PlantItem {tag: 'F-2702'}), (b:PlantItem {tag: 'V-3501'})
RETURN EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
    WHERE x.tag <> 'XV-32003' AND y.tag <> 'XV-32003')+ (b)
} AS reachable_without_XV_32003;

MATCH (a:PlantItem {tag: 'P-2502'}), (b:PlantItem {tag: 'P-5102'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((n:PlantItem)-[:line_to]->(m:PlantItem)
                    WHERE n.tag <> 'XV-39002' AND m.tag <> 'XV-39002')+ (b)
       } AS can_flow

MATCH (a:PlantItem {tag: 'D-1601'}), (b:PlantItem {tag: 'EA-1601'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE y.tag IS NULL OR y.tag <> 'T-1601')+ (b)
       } AS reachable_without_T1601

MATCH (:PlantItem {tag: 'XV-18002'})-[:line_to]->(item:PlantItem)
RETURN DISTINCT item.tag AS tag
