MATCH (:PlantItem {tag: 'F-201'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (k:PlantItem {tag: 'K-2101'}), (v:Valve)
WHERE EXISTS { (k)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (k:PlantItem {tag: 'K-1401'}), (v:Valve)
WHERE EXISTS { (k)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e:Equipment) WHERE e <> k }
  AND NOT v:CheckValve
  AND NOT v:GlobeCheckValve
  AND NOT v:SwingCheckValve
  AND NOT EXISTS { (:PlantItem)-[:control]->(v) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag
